    add t4, t1, a2
    lbu t3, 0(t3) #face
    lbu t4, 0(t4) #turns
    sw t3, 16(sp)
    sw t4, 20(sp)
    lw t4, 20(sp)      # get turns
    sw t4, 40(sp)      # save remaining
    lw t5, 4(sp)       # get original input pointer
    sw t5, 44(sp)      # save current source
turn_loop:
    #t0 = remaining
    #t1 = remaining & 1
    #t2 = destination pointer
    lw t0, 40(sp) # load remaining
    beqz t0, done_apply
    andi t1, t0, 1 #odd or even
    bnez t1, odd
    addi t2, sp, 24
    sw t2, 12(sp)
    j have_destination
odd:
    lw t2, 8(sp)
    sw t2, 12(sp)
    j have_destination
have_destination:
    lw a0, 44(sp) #current source
    lw a1, 12(sp) #destination
    lw a2, 16(sp) #face
    jal ra quarter_turn_p
    lw a0, 44(sp) #current source
    lw a1, 12(sp) #destination
    lw a2, 16(sp) #face
    jal ra quarter_turn_o
    lw t3, 12(sp) #current source = destination
    sw t3, 44(sp)
    lw t0, 40(sp) #remaining
    addi t0, t0, -1
    sw t0, 40(sp)
    j turn_loop    
done_apply:
    lw ra, 0(sp)
    addi sp, sp, 48
    ret
    
quarter_turn_p:
    #a0 = input state pointer
    #a1 = output state pointer
    #a2 = face
    li t0, 0 #i=0
    li t1, 7 
    la t5, source
loop_qp:
    bge t0, t1, done_qp
    slli t2, a2, 3 #t2=face<<3
    sub t2, t2, a2 #t2=face*7
    add t2, t2, t0 #offset
    add t3, t5, t2
    lbu t3, 0(t3) #from=source[face][i]
    add t4, a0, t3
    lbu t4, 0(t4) #state.p[from]
    add t6, a1, t0
    sb t4, 0(t6)
    addi t0, t0, 1
    j loop_qp
done_qp:
    ret
    
quarter_turn_o:
    # a0 = input state pointer
    # a1 = output state pointer
    # a2 = face
    li t0, 0
    li t1, 7
    la t5, source
    la t6, twist
    la a3, mod3_table
loop_qo:
    bge t0, t1, done_qo
    slli t2, a2, 3
    sub  t2, t2, a2
    add  t2, t2, t0 #offset=face*7+i
    add  t3, t5, t2
    lbu  t3, 0(t3) #from=source[face][i]
    addi t4, a0, 7
    add  t4, t4, t3
    lbu  t4, 0(t4) #old o=state.o[from]
    add  t3, t6, t2
    lbu  t3, 0(t3) #twist=twist[face][i]
    add  t4, t4, t3 #sum=old o+twist
    add  t3, a3, t4
    lbu  t4, 0(t3) #new o=mod3_table[sum]
    addi t3, a1, 7
    add  t3, t3, t0
    sb   t4, 0(t3) #result.o[i]=new o
    addi t0, t0, 1
    j loop_qo
done_qo:
    ret
    
heuristic:
    addi sp, sp, -16
    sw ra, 0(sp) #save return address
    sw a0, 4(sp) #save state pointer
    jal ra, permutation_rank
    sw a0, 8(sp)
    lw a0, 4(sp) #a0=state pointer
    jal ra, orientation_rank
    sw a0, 12(sp)
    la a1, table_p
    lw a5, 8(sp)
    add a1, a1, a5
    la a2, table_o
    lw a4, 12(sp)
    add a2, a2, a4
    lbu t1, 0(a1) #hp
    lbu t2, 0(a2) #ho
    bge t1, t2, hp
    mv t3, t2
continue_h:
    mv a0, t3 #a0=result
    lw ra, 0(sp)
    addi sp, sp, 16
    ret
hp:
    mv t3, t1
    j continue_h
permutation_rank:
    li t0, 0 #p
    li t1, 0 #i
    li t2, 0 #j
    li t3, 7 #7
loop_1:
    bge t1, t3, done_p
    li t4, 0 #smaller
    addi t2, t1, 1 # j=i+1
loop_2:
    bge t2, t3, loop_1_done
    add a1, a0, t2
    add a2, a0, t1
    lbu t5, 0(a2)
    lbu t6, 0(a1)
    addi t2, t2, 1
    bge t6, t5, loop_2
    addi t4, t4, 1
    j loop_2
loop_1_done:
    sub a1, t3, t1 #a1=7-i
    mv a2, t0 #a2=old p
    li t6, 0 #t6=result
multiply_loop:
    beqz a1, multiply_done
    add t6, t6, a2 #result=result+old p
    addi a1, a1, -1 #a1--
    j multiply_loop
multiply_done:
    add t0, t6, t4
    addi t1, t1, 1
    j loop_1
done_p:
    mv a0, t0
    ret

orientation_rank:
    li t0, 0
    li t1, 0
    li t2, 6
    addi t3, a0, 7
loop:
    bge t1, t2, done_o
    lbu t4, 0(t3)
    slli t5, t0, 1
    add t0, t0, t5
    add t0, t0, t4
    addi t1, t1, 1
    addi t3, t3, 1
    j loop
done_o:
    mv a0, t0
    ret